import type { BankQuestion } from "@/lib/bank";

/** Statements, Assumptions, Arguments and Course of Action (Reasoning): 160 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "reason-critical-reasoning-1", "question": "Statement: 'Use Glow soap for soft and healthy skin.' (an advertisement) Assumptions: I. People want soft and healthy skin. II. Advertisements influence what people buy.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 2, "explanation": "The advert sells the soap on the promise of soft, healthy skin, which assumes people want that (I). Advertising at all assumes ads affect buying (II). Both are implicit.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-2", "question": "Statement: 'The school will remain closed tomorrow because heavy rain has been forecast.' (a notice) Assumptions: I. The weather forecast is reliable enough to act upon. II. Students dislike rainy days.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 0, "explanation": "Closing the school on the strength of a forecast assumes the forecast can be trusted (I). Students' feelings about rain play no part in the decision, so II is not implicit.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-3", "question": "Statement: Several cases of dengue have been reported from a residential colony. Courses of action: I. The municipal body should carry out fogging and clear stagnant water in the colony. II. All residents of the colony should be shifted elsewhere.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Dengue spreads through Aedes mosquitoes breeding in stagnant water, so fogging and clearing water deals with the cause (I). Moving everyone out is impractical and out of proportion (II).", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-4", "question": "Should mobile phones be banned in classrooms during lessons? Arguments: I. No, almost everyone owns a phone nowadays. II. Yes, phones in class distract students and disrupt teaching.", "options": ["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"], "answer": 1, "explanation": "II gives a real reason linked to learning. I is weak, because how common phones are has no bearing on whether they should be used during lessons.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-5", "question": "Statement: All the committee members who attended the meeting voted for the proposal, which was passed unanimously by those present. Conclusions: I. Every member of the committee attended the meeting. II. No member who was present voted against the proposal.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "'Unanimously by those present' means nobody present opposed it, so II follows. Nothing says every member was present, so I does not follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-6", "question": "Statement: 'Submit your application before 15 March to be considered for the scholarship.' (a university notice) Assumptions: I. Applications received after 15 March may not be considered. II. The university expects some students to apply for the scholarship.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 2, "explanation": "Setting a deadline implies late applications may be rejected (I). Issuing the notice at all assumes there will be applicants (II). Both are implicit.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-7", "question": "Statement: A large number of students of a government school failed in mathematics in the Class X board examination this year. Courses of action: I. All the mathematics teachers of the school should be dismissed immediately. II. The school should review its mathematics teaching and arrange remedial classes.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "II tackles the problem in a constructive way. I is a harsh step taken without any inquiry; the failures could have other causes, so dismissing teachers at once does not follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-8", "question": "Should voting be made compulsory in India? Arguments: I. Yes, it would raise turnout and make election results more representative. II. No, forcing people to vote may produce uninformed or random votes and takes away the freedom not to vote.", "options": ["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"], "answer": 2, "explanation": "Both arguments are relevant and carry weight. I points to higher, more representative turnout. II points to poor-quality votes and lost freedom of choice. Both are strong.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-9", "question": "Statements: I. The price of onions has risen sharply in city markets. II. Unseasonal rain has destroyed a large part of the onion crop in the major producing states.", "options": ["Statement I is the cause and statement II is its effect", "Statement II is the cause and statement I is its effect", "Both statements are effects of independent causes", "Both statements are effects of some common cause"], "answer": 1, "explanation": "Crop damage (II) cuts supply, which pushes up prices (I). So II is the cause and I is its effect.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-10", "question": "Statement: To reduce traffic jams, the city administration has decided to allow private cars with odd and even number plates on alternate weekdays. Assumptions: I. People will stop buying cars. II. The scheme will reduce the number of cars on the roads on any given day.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 1, "explanation": "The scheme works only if it cuts the number of cars on the road each day (II). Nothing in it depends on people no longer buying cars, so I is not implicit.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-11", "question": "Statement: Most of the students who joined the coaching course cleared the examination. Conclusions: I. The coaching course guarantees success in the examination. II. Some of the students who joined the course cleared the examination.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "If most cleared it, then certainly some did (II). 'Most' is not 'all', and the course is not shown to be the cause, so the guarantee in I does not follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-12", "question": "Statement: Road accidents on a particular stretch of highway have doubled in the past year, and most of them occurred at night. Courses of action: I. Street lights and reflective signboards should be installed on the stretch. II. Night-time speed checks should be stepped up on the stretch.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "Most accidents happen at night, so better lighting and signs (I) and stricter night-time speed checks (II) both address the likely causes. Both follow.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-13", "question": "Statement: 'Only candidates who scored at least 60% in graduation are eligible for the post.' (an advertisement) Assumptions: I. Candidates who scored less than 60% may not be suitable for the job. II. Graduates with more than 60% marks always make better employees.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 0, "explanation": "A cut-off assumes that those below it are less likely to suit the job (I). 'Always' makes II an extreme claim the employer need not hold.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-14", "question": "Should all private schools in India be nationalised? Arguments: I. Yes, this is the only way to ensure quality education for all children. II. No, private schools in many European countries are doing well.", "options": ["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"], "answer": 3, "explanation": "I is weak because it claims nationalisation is the 'only way', which is an overstatement. II is weak because the success of schools in Europe does not show how Indian schools should be run. Neither is strong.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-15", "question": "Statement: A survey shows that many rural primary schools have only one teacher for all five classes. Courses of action: I. The government should immediately close such schools and merge them with larger schools far away. II. The government should recruit additional teachers and post them to these schools.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "Posting more teachers (II) fixes the shortage directly. Closing the schools (I) would push young children to travel far or drop out, which defeats the aim. Only II follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-16", "question": "Statement: No honest person tells lies. Some politicians tell lies. Conclusions: I. Some politicians are not honest. II. No politician is honest.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "The politicians who lie cannot be honest, so some politicians are not honest (I). Nothing is said about the politicians who do not lie, so II does not follow.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-17", "question": "Statement: The government has decided to raise the fees of all government colleges by 10% from the next session. Assumptions: I. Students will stop going to government colleges. II. The present fees do not cover any part of the colleges' running costs.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 3, "explanation": "A 10% rise does not assume students will stop enrolling. If anything, it assumes they will keep coming, so I is wrong. II is extreme ('any part'); the government need only think the fees are too low. Neither is implicit.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-18", "question": "Statements: I. Many trains to Shimla were cancelled this week. II. Schools in Shimla remained closed this week.", "options": ["Statement I is the cause and statement II is its effect", "Statement II is the cause and statement I is its effect", "Both statements are effects of independent causes", "Both statements are effects of some common cause"], "answer": 3, "explanation": "Neither event causes the other. Both are likely results of a common cause such as heavy snowfall or landslides in the region.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-19", "question": "Passage: India's exports of software services rose by 12 per cent last year, even as global demand for technology services slowed. Analysts attribute the growth mainly to new contracts in the banking and healthcare sectors. Inference: Last year India's software service exports grew despite a global slowdown in demand for such services. How is the inference best described?", "options": ["Definitely true", "Probably true", "Data inadequate", "Definitely false"], "answer": 0, "explanation": "The passage directly says exports rose 12% 'even as global demand… slowed', so the inference is definitely true.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-20", "question": "Passage: A state's farm output fell sharply last year after the monsoon arrived three weeks late and rainfall was 30 per cent below normal. Districts with good irrigation were the least affected. Inference: A large share of the state's farmland depends on rainfall rather than irrigation. How is the inference best described?", "options": ["Definitely true", "Probably true", "Data inadequate", "Definitely false"], "answer": 1, "explanation": "Output fell sharply while irrigated districts held up, which suggests much of the farmland is rain-fed. The passage gives no figure, so it is probably true, not definitely true.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-21", "question": "Statement: Several cases of food poisoning were reported among guests at a wedding in a town. Courses of action: I. The government should ban all wedding feasts in the town. II. The local health authorities should collect samples of the food served and investigate the caterer.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "Testing the food and investigating the caterer (II) is the sensible response. A blanket ban on all wedding feasts (I) is out of proportion to one incident.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-22", "question": "Should the use of thin plastic carry bags be completely banned in India? Arguments: I. No, a ban would make shopping slightly inconvenient for people. II. Yes, such bags clog drains and harm animals and the environment.", "options": ["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"], "answer": 1, "explanation": "II names serious, relevant harms. I points only to minor inconvenience, which cannot outweigh environmental damage, so it is weak.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-23", "question": "Statement: 'The railway has introduced online ticket booking so that passengers need not stand in long queues.' Assumptions: I. Many passengers have access to the internet. II. Standing in queues is an inconvenience that passengers would like to avoid.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 2, "explanation": "Online booking helps only if passengers can get online (I), and the stated aim assumes queues are a nuisance worth avoiding (II). Both are implicit.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-24", "question": "A councillor claims: 'The city's new cycle lanes have caused a rise in traffic congestion.' Which of the following, if true, most weakens the claim?", "options": ["Some motorists dislike the cycle lanes", "The cycle lanes took away a car lane on some roads", "Congestion rose by about the same amount over the same period in neighbouring cities that built no cycle lanes", "Cyclists sometimes ignore traffic signals"], "answer": 2, "explanation": "If congestion rose just as much in cities without cycle lanes, some other common factor is the likely cause, which undermines the claim. The lost car lane would, if anything, support the councillor.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-25", "question": "Statement: The state government will give free laptops only to those Class XII students who score above 85% in the board examination. Kavya received a free laptop under the scheme. Conclusions: I. Kavya scored above 85% in the board examination. II. Every student who scores above 85% will receive a laptop.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "'Only those above 85%' makes scoring above 85% a necessary condition, so Kavya must have scored above 85% (I). It is not a sufficient condition (the word is 'only', not 'all'), so II does not follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-26", "question": "Statement: Groundwater levels in several districts of a state have fallen sharply over the last decade because of over-extraction for paddy cultivation. Courses of action: I. The state should offer farmers incentives to shift to less water-hungry crops in these districts. II. The state should promote rainwater harvesting and recharge structures in these districts. III. The state should ban all agriculture in these districts.", "options": ["Only I and II follow", "Only II and III follow", "Only I and III follow", "All I, II and III follow"], "answer": 0, "explanation": "Shifting crops (I) cuts extraction and recharge (II) adds water, so both are practical. A total ban on farming (III) would wreck livelihoods and is extreme.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-27", "question": "Statement: 'To attract more tourists, the state tourism department will promote its heritage sites through social media campaigns aimed at young travellers.' Assumptions: I. Young travellers use social media. II. Heritage sites can interest young travellers. III. Older travellers do not visit heritage sites.", "options": ["Only I is implicit", "Only II and III are implicit", "Only I and II are implicit", "All I, II and III are implicit"], "answer": 2, "explanation": "The campaign makes sense only if young travellers are on social media (I) and can be drawn to heritage sites (II). Targeting the young does not mean older travellers never visit (III).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-28", "question": "Should higher education be made completely free for all students in India? Arguments: I. Yes, it would let talented students from poor families study further. II. No, it would put a heavy burden on public finances and subsidise well-off families who can afford the fees.", "options": ["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"], "answer": 2, "explanation": "I points to wider access for poor but talented students. II points to the fiscal cost and to the subsidy going to the rich. Both are relevant and serious, so both are strong.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-29", "question": "Statements: I. The central bank raised its key policy interest rate by 50 basis points. II. Commercial banks increased their lending rates on home loans.", "options": ["Statement I is the cause and statement II is its effect", "Statement II is the cause and statement I is its effect", "Both statements are effects of independent causes", "Both statements are effects of some common cause"], "answer": 0, "explanation": "When the central bank raises its policy rate, banks' cost of funds goes up and they pass it on through higher lending rates. So I is the cause and II is the effect.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-30", "question": "Passage: The new metro line, opened in March, carried an average of 40,000 passengers a day in its first month, well below the projected 1,00,000. Ridership has risen every month since but is still only about half the projection. Inference: The metro line's daily ridership has exceeded its projection every month since the second month. How is the inference best described?", "options": ["Definitely true", "Probably true", "Data inadequate", "Definitely false"], "answer": 3, "explanation": "The passage says ridership is 'still only about half the projection', so it has never exceeded it. The inference contradicts the passage and is definitely false.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-31", "question": "Passage: A drug company has announced that its new vaccine showed 90 per cent efficacy in trials involving 20,000 adults aged 18 to 60. Inference: The vaccine is equally effective in children. How is the inference best described?", "options": ["Definitely true", "Probably true", "Data inadequate", "Definitely false"], "answer": 2, "explanation": "The trial covered only adults aged 18–60, so the passage gives no basis for judging the effect in children either way. The data are inadequate.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-32", "question": "A company claims: 'Our new training programme raised employee productivity, because employees who completed it produced 20% more than those who did not.' The claim assumes that:", "options": ["productivity cannot be measured accurately", "every employee completed the programme", "the programme was expensive to run", "the employees who chose to complete the programme were not already more productive than those who did not"], "answer": 3, "explanation": "If keener, already more productive employees were the ones who completed the course, the 20% gap would not show that the programme worked. The claim therefore assumes there was no such difference. 'Every employee completed it' contradicts the comparison.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-33", "question": "Statement: There has been a sudden rise in cyber-fraud cases in which elderly people are tricked into sharing bank OTPs. Courses of action: I. Banks should run awareness campaigns aimed at elderly customers. II. Banks should stop sending OTPs altogether. III. The police should set up a dedicated helpline for reporting such fraud.", "options": ["Only I and II follow", "Only I and III follow", "Only II and III follow", "All I, II and III follow"], "answer": 1, "explanation": "Awareness (I) and a reporting helpline (III) tackle the fraud directly. Scrapping OTPs (II) would remove a key security layer and expose every customer to greater risk.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-34", "question": "Statement: Of the 200 employees of a firm, 120 speak Hindi, 90 speak English and 30 speak neither language. Conclusions: I. At least 40 employees speak both languages. II. Exactly 40 employees speak both languages. III. More employees speak only Hindi than only English.", "options": ["Only I follows", "Only I and II follow", "Only II and III follow", "All I, II and III follow"], "answer": 3, "explanation": "Employees who speak at least one language = 200 − 30 = 170. Both = 120 + 90 − 170 = 40, so II follows, and so does I (40 is at least 40). Only Hindi = 120 − 40 = 80 and only English = 90 − 40 = 50, so III follows. All three follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-35", "question": "Should coaching institutes be regulated by law? Arguments: I. Yes, many charge very high fees and make misleading claims about their results. II. No, every business should be free to do whatever it wants. III. Yes, students in some institutes face extreme stress with no support system.", "options": ["Only I and II are strong", "Only II and III are strong", "Only I and III are strong", "All I, II and III are strong"], "answer": 2, "explanation": "I (misleading claims, high fees) and III (student welfare) are serious, relevant reasons. II is weak, because no business is free to do 'whatever it wants'; that is an absolute claim.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-36", "question": "Statement: 'Despite repeated reminders, many citizens have still not linked their PAN with Aadhaar; the deadline has been extended once again.' (a news report) Assumptions: I. Some citizens may link their PAN with Aadhaar before the new deadline. II. Every citizen will link PAN with Aadhaar before the new deadline.", "options": ["Only assumption I is implicit", "Only assumption II is implicit", "Both I and II are implicit", "Neither I nor II is implicit"], "answer": 0, "explanation": "Extending the deadline makes sense only if more people are expected to comply in the extra time (I). Expecting every single citizen to comply (II) is extreme and not needed.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-37", "question": "Argument: 'Students who eat breakfast score higher in examinations. Therefore, the school should serve free breakfast to raise examination scores.' Which of the following, if true, most seriously weakens the argument?", "options": ["Free breakfast schemes are popular with parents", "Some students skip breakfast because they wake up late", "Students who eat breakfast at home mostly come from families that also provide tuition and study support", "Breakfast is widely called the most important meal of the day"], "answer": 2, "explanation": "If breakfast-eaters also get tuition and study support at home, that support, not breakfast, may explain their higher scores. Free breakfast alone might then not raise scores. The other options leave the causal link untouched.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-38", "question": "Passage: Since the city introduced a congestion charge on cars entering the central zone during working hours, average traffic speed in the zone has risen by 15 per cent and the number of bus passengers entering the zone has grown by 10 per cent. Inference: Some people who earlier drove into the central zone now travel there by bus. How is the inference best described?", "options": ["Definitely true", "Probably true", "Data inadequate", "Definitely false"], "answer": 1, "explanation": "Fewer cars (faster traffic) together with more bus passengers suggests that some drivers switched to buses. The passage does not confirm who the new passengers are, so the inference is probably true.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-39", "question": "Statement: 'Every citizen should help keep public places clean; the government alone cannot keep the city clean.' (the mayor) Conclusions: I. The government's efforts alone are not enough to keep the city clean. II. The government should stop its own cleanliness drive.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "I restates the mayor's point that the government alone cannot do it. The mayor asks citizens to join in, not for the government to stop, so II does not follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "reason-critical-reasoning-40", "question": "Statements: I. The government reduced the excise duty on petrol. II. Sales of woollen garments rose sharply this winter.", "options": ["Statement I is the cause and statement II is its effect", "Statement II is the cause and statement I is its effect", "Both statements are effects of independent causes", "Both statements are effects of some common cause"], "answer": 2, "explanation": "A cut in petrol duty has nothing to do with winter demand for woollens, which rises because of the cold. The two are effects of independent causes.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id":"reason-critical-reasoning-41","question":"Statement: 'Carry an umbrella; it may rain this evening,' a mother tells her son. Assumptions: I. An umbrella can protect the son from the rain. II. The son will not go out this evening.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"The advice makes sense only if the umbrella will help against rain (I). Advising him to carry it implies she expects him to go out, so II contradicts the statement.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-42","question":"Statement: 'Residents are requested to switch off the corridor lights during the daytime to save electricity.' (a notice in a housing society) Assumptions: I. Corridor lights are sometimes left on during the day. II. Residents are likely to act on the request.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":2,"explanation":"The notice would be pointless if the lights were never left on in daytime (I), and issuing a request assumes residents may follow it (II). Both are implicit.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-43","question":"Statement: 'The bank will open branches in 200 villages to bring unbanked households into the formal banking system.' Assumptions: I. Many households in these villages do not have bank accounts. II. Villagers prefer to keep their savings in cash at home.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"The plan targets 'unbanked households', so it assumes such households exist in these villages (I). Whether villagers prefer cash is not something the bank's plan depends on; if anything, it hopes they will use the branches. Only I is implicit.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-44","question":"Statement: 'Book your tickets at least a week in advance to avoid last-minute disappointment.' (a travel agency advertisement) Assumptions: I. Tickets may get sold out close to the date of travel. II. Travellers would like to avoid disappointment at the last minute.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":2,"explanation":"'Last-minute disappointment' can arise only if tickets may run out near the date (I), and the appeal works only if travellers want to avoid it (II). Both are implicit.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-45","question":"Statement: The municipal corporation has announced a 50% rebate on property tax for buildings that install rooftop solar panels. Assumptions: I. The rebate may encourage owners to install solar panels. II. All buildings in the city already have solar panels.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"An incentive is offered on the belief that it will change behaviour (I). If every building already had panels the scheme would be meaningless, so II is not implicit; it runs against the statement.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-46","question":"Statement: 'Instead of raising the price of the newspaper, we will increase the number of advertisement pages to meet rising costs,' says a publisher. Assumptions: I. Extra advertisement revenue can make up for the rising cost of production. II. Readers will not stop buying the paper because it carries more advertisements.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":2,"explanation":"The plan works only if the extra ad income covers the costs (I) and readership holds up, since advertisers pay for readers (II). Both are implicit.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-47","question":"Statement: 'Employees who complete the online cyber-security module by 30 June will receive a certificate.' (an office circular) Assumptions: I. A certificate will motivate employees to complete the module on time. II. The module cannot be accessed after 30 June.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"Linking a certificate to the deadline assumes it acts as an incentive (I). The circular says only that late finishers get no certificate; it does not imply the module is closed after 30 June. Only I is implicit.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-48","question":"Statement: 'The convocation will be held in the open ground next month instead of the auditorium, so that parents too can attend.' (a college notice) Assumptions: I. The auditorium is in a poor condition. II. The weather next month is expected to allow an outdoor function.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":1,"explanation":"The reason given is space for parents, not the auditorium's condition, so I is not implicit. Planning an outdoor function a month ahead assumes the weather will allow it (II).","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-49","question":"Statement: 'Senior citizens get 0.5% extra interest on all fixed deposits with us.' (a bank advertisement) Assumptions: I. Senior citizens have more money than other customers. II. Extra interest can attract senior citizens to place deposits with the bank.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":1,"explanation":"The offer is meant to draw senior citizens, so it assumes the extra interest appeals to them (II). It does not need them to be richer than others (I).","difficulty":"hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-50","question":"Statement: Mr. Rao, a civil engineer, has been appointed head of the city's water-supply board. Assumptions: I. Only engineers can manage a water-supply board. II. Mr. Rao was the only person who applied for the post.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":3,"explanation":"Appointing an engineer suggests his background is useful, not that only engineers can do the job; 'only' makes I extreme. Nothing hints that he was the sole applicant (II). Neither is implicit.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-51","question":"Statement: 'Visit the new science museum—entry is free for students on weekdays.' (an advertisement) Assumptions: I. Students do not visit museums on weekends. II. The museum earns enough from adult tickets to run without any other support.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":3,"explanation":"Free weekday entry aims to draw students on days that are otherwise quiet; it does not assume students never come on weekends (I). The advert says nothing about how the museum is funded (II). Neither is implicit.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-52","question":"Statement: In view of the falling number of students choosing science, the education board has decided to cut science seats in its colleges by 20% from next year. Assumptions: I. The fall in demand for science seats is likely to continue next year. II. Seats in arts and commerce will be raised by exactly 20%.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"Cutting seats for next year makes sense only if low demand is expected to continue (I). The decision says nothing about other streams, let alone an exact 20% rise (II).","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-53","question":"Statement: 'Gold loans disbursed within 30 minutes—no income proof needed.' (a finance company advertisement) Assumptions: I. Some borrowers need money urgently. II. Some borrowers find it difficult to produce proof of income.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":2,"explanation":"Speed is advertised because some borrowers need cash fast (I), and dropping the income-proof requirement is advertised because some find it hard to provide (II). Both are implicit.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-54","question":"Statement: The airline has decided to stop serving free meals on flights shorter than two hours. Assumptions: I. Passengers on short flights will stop flying with the airline. II. Free meals on short flights are a cost the airline can cut without losing many passengers.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":1,"explanation":"The airline would not cut meals if it expected to lose passengers, so I runs against the decision. The decision assumes the saving is worth it and passengers will mostly stay (II).","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-55","question":"Statement: 'Sanskrit should be made a compulsory subject in all schools of the state to preserve the language,' says a scholar. Assumptions: I. Making a subject compulsory in schools helps keep a language alive. II. Sanskrit is not taught in any school of the state at present.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":0,"explanation":"The scholar's remedy works only if compulsory study helps preserve a language (I). Making it compulsory in 'all' schools does not imply it is taught in none today; it may be optional in some (II).","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-56","question":"Statement: 'The hospital has installed an automated token system in its outpatient department to cut waiting time.' (a news report) Assumptions: I. Patients will no longer need to see doctors in person. II. The hospital has stopped all manual registration.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":3,"explanation":"A token system organises the queue; it does not assume patients skip doctors (I). Nothing says manual registration has been stopped completely (II). Neither is implicit.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-57","question":"Statement: 'Our party will waive all farm loans if voted to power,' says a political leader at a rally. Assumptions: I. Every farmer in the state has taken a farm loan. II. The promise of a loan waiver can win the party votes.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":1,"explanation":"A poll promise assumes it will attract voters (II). The waiver applies to those who have loans; it does not assume every farmer has one (I).","difficulty":"very-hard","source":"State PSC · SSC CGL"},
  {"id":"reason-critical-reasoning-58","question":"Statement: From next month, only vehicles carrying a valid pollution-under-control (PUC) certificate will be allowed to refuel at petrol pumps in the city. Assumptions: I. Vehicle owners will get PUC certificates so that they can refuel. II. Petrol-pump staff can check the certificate before refuelling.","options":["Only assumption I is implicit","Only assumption II is implicit","Both I and II are implicit","Neither I nor II is implicit"],"answer":2,"explanation":"The rule aims to push owners to get certified (I), and it can work only if pumps can verify certificates (II). Both are implicit.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-59","question":"Statement: The library is open from 9 a.m. to 8 p.m. from Monday to Saturday and is closed on Sundays. Conclusions: I. A reader cannot use the library on a Sunday. II. The library is open for 66 hours a week.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"It is closed on Sundays, so I follows. It is open 11 hours a day for 6 days = 66 hours, so II follows too.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-60","question":"Statement: Every student of Section B passed the mid-term test. Rohit failed the mid-term test. Conclusions: I. Rohit is not a student of Section B. II. No student of Section B failed the mid-term test.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"If Rohit were in Section B he would have passed, so he is not (I). 'Every student of Section B passed' is the same as 'none of them failed' (II). Both follow.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-61","question":"Statement: The price of a 1 kg packet of tea went up from ₹400 to ₹500. Conclusions: I. The price of the packet rose by 25%. II. People are now buying less tea.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The rise is ₹100 on ₹400, i.e. 25%, so I follows. The statement says nothing about how much tea people buy, so II does not follow.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-62","question":"Statement: In a survey, 70% of the respondents from a town said they read a newspaper every day. Conclusions: I. 30% of the town's residents never read a newspaper. II. A majority of the respondents said they read a newspaper daily.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"70% is a majority of the respondents, so II follows. The other 30% did not say they read daily; they may read sometimes, and respondents are not the whole town. So I does not follow.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-63","question":"Statement: The annual meeting of the society will be held either on Monday or on Tuesday next week, not on both days. Conclusions: I. The meeting will be held on Monday. II. The meeting will be held on Tuesday.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Exactly one of the two must be true but we cannot say which, so neither follows on its own while 'either I or II' follows.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-64","question":"Statement: No car in the showroom costs less than ₹6 lakh, and the costliest car in the showroom is priced at ₹18 lakh. Conclusions: I. Every car in the showroom is priced from ₹6 lakh to ₹18 lakh. II. The showroom has a car priced at ₹12 lakh.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The lowest possible price is ₹6 lakh and the highest is ₹18 lakh, so every price lies in that range (I). Nothing says any car is priced exactly ₹12 lakh (II).","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-65","question":"Statement: By law, the warning 'Tobacco is injurious to health' must be printed on every cigarette packet sold in the country. Conclusions: I. A cigarette packet sold without the warning breaks the law. II. Printing the warning has reduced smoking in the country.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Since the warning is compulsory, selling a packet without it is unlawful (I). The statement gives no information about the effect of the warning on smoking (II).","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-66","question":"Statement: Of the 60 employees of an office, 45 travel by metro and 25 travel by bus; some employees may use neither. Conclusions: I. At least 10 employees use both the metro and the bus. II. At most 25 employees use both the metro and the bus.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Users of at least one mode ≤ 60, so both ≥ 45 + 25 − 60 = 10 (I). The number using both cannot exceed the smaller group, 25 (II). Both follow.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-67","question":"Statement: Anita is older than Bina, and Bina is older than Charu. Deepa is younger than Anita. Conclusions: I. Charu is the youngest of the four. II. Anita is the oldest of the four.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Anita is older than Bina, Charu and Deepa, so she is the oldest (II). Deepa is only known to be younger than Anita; she could be younger than Charu, so I does not follow.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-68","question":"Statement: A shop gives a 10% discount on all bills above ₹2,000 and, for card payments, a further 5% off the discounted amount. Conclusions: I. A customer whose bill is ₹3,000 and who pays by card pays ₹2,565. II. Card payments on bills above ₹2,000 get a total discount of 15%.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"3,000 × 0.90 × 0.95 = 2,565, so I follows. Successive discounts of 10% and 5% equal 1 − 0.9 × 0.95 = 14.5%, not 15%, so II does not follow.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-69","question":"Statement: All trains from the city's main station to Pune leave before noon. Train X leaves the main station at 2 p.m. Conclusions: I. Train X goes to Pune. II. No train from any station in the city goes to Pune in the afternoon.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Train X leaves the main station after noon, so it cannot be a Pune train; I is false. The rule covers only the main station, so trains from other stations are not covered and II does not follow. Neither follows.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-70","question":"Statement: Only graduates are allowed to apply for the post. Some of the applicants are engineers. Conclusions: I. All the applicants are graduates. II. Some graduates are engineers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"'Only graduates can apply' means every applicant is a graduate (I). The engineers among the applicants are therefore graduates, so some graduates are engineers (II). Both follow.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-71","question":"Statement: A company's profit this year was ₹50 crore, which is 25% more than last year. Last year's profit was 20% less than the profit of the year before. Conclusions: I. The profit two years ago was more than this year's profit. II. Last year's profit was ₹40 crore.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Last year = 50 ÷ 1.25 = ₹40 crore (II follows). Two years ago = 40 ÷ 0.8 = ₹50 crore, which equals this year's profit, so I does not follow.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-72","question":"Statement: In a class, every student who plays chess also plays carrom, and no student who plays carrom plays cricket. Conclusions: I. Some chess players in the class play cricket. II. No chess player in the class plays cricket.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":1,"explanation":"Every chess player plays carrom, and no carrom player plays cricket, so no chess player plays cricket (II). I contradicts this. This is not an 'either–or' case because II is definite.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-73","question":"Statement: Exactly three of the five bulbs in a room are switched on, and every bulb that is switched on is an LED bulb. Conclusions: I. The bulbs that are switched off are not LED bulbs. II. There are at least three LED bulbs in the room.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The three bulbs that are on are LEDs, so at least three LEDs exist (II). The statement says nothing about the bulbs that are off; they may or may not be LEDs, so I does not follow.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-74","question":"Statement: 'The new tax regime will benefit taxpayers whose annual income is below ₹12 lakh,' said the finance secretary. Conclusions: I. Taxpayers earning more than ₹12 lakh will have to pay more tax than before. II. No taxpayer earning below ₹12 lakh will be worse off in any way.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Saying one group benefits says nothing about higher earners paying more (I). 'Benefit' for a group does not guarantee that no individual in it is worse off in any way (II), which is extreme. Neither follows.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-75","question":"Statement: A large tree has fallen across the main road after last night's storm, blocking all traffic. Courses of action: I. The municipal staff should remove the tree at once. II. The road should be closed permanently.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Clearing the tree (I) solves the immediate problem. Closing the road for good (II) is an overreaction to a one-time event.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-76","question":"Statement: Many passengers have complained that the drinking water at a railway station tastes bad and may be contaminated. Courses of action: I. The railway should get the water tested and repair the supply if needed. II. Passengers should be advised to use bottled water until the problem is fixed.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Testing and repair (I) fixes the cause, and a temporary advisory (II) protects passengers meanwhile. Both are practical.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-77","question":"Statement: A bank finds that several of its ATMs in a district frequently run out of cash on weekends. Courses of action: I. The bank should load more cash into these ATMs before weekends. II. The bank should shut down all its ATMs in the district.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Loading more cash before weekends (I) tackles the shortage directly. Shutting all ATMs (II) would make things worse.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-78","question":"Statement: A newly opened private school is charging fees far above the limit set by the state's fee-regulation committee. Courses of action: I. All students of the school should be shifted to other schools immediately. II. The committee should issue a notice to the school and order it to refund the excess fees.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"A notice and refund order (II) enforces the rule against the wrongdoer. Uprooting every student (I) punishes the children rather than the school.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-79","question":"Statement: The number of students dropping out of college in their first year has risen sharply in a state, mainly because of financial difficulties. Courses of action: I. The state should offer need-based scholarships to first-year students. II. The state should make college attendance compulsory by law.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Scholarships (I) address the stated cause, financial hardship. Compelling attendance by law (II) does nothing for students who cannot afford college.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-80","question":"Statement: Several residents of a colony fell ill after drinking tap water, and tests found sewage mixing with the supply line. Courses of action: I. The supply line should be repaired and the water disinfected before supply is resumed. II. The officials responsible for maintaining the line should be asked to explain the lapse.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Repair and disinfection (I) removes the hazard, and seeking an explanation (II) fixes accountability without punishing anyone in advance. Both follow.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-81","question":"Statement: A popular online shopping site has been found to be selling counterfeit branded goods through some of its sellers. Courses of action: I. The government should ban all online shopping. II. The site should be penalised and made to remove the sellers of fake goods.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Penalising the site and removing the offending sellers (II) targets the wrongdoing. Banning all online shopping (I) hurts every honest seller and buyer.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-82","question":"Statement: After an unusually long dry spell, the reservoir that supplies a city is down to 10% of its capacity. Courses of action: I. The city should stop supplying water to hospitals. II. The city should cancel all construction projects for the next five years.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Cutting water to hospitals (I) would endanger lives, and a five-year ban on construction (II) is far out of proportion to a seasonal shortage. Rationing would be sensible, but neither given action follows.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-83","question":"Statement: Tomato prices have shot up in a state after transporters went on an indefinite strike. Courses of action: I. The government should hold talks with the transporters to end the strike. II. The government should ban the sale of tomatoes until prices come down.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Talks to end the strike (I) restore supply, which brings prices down. A ban on sales (II) would leave consumers with no tomatoes at all.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-84","question":"Statement: Many elderly pensioners find it hard to reach the pension office, which is on the fourth floor of a building with no lift. Courses of action: I. The office should be moved to the ground floor or a lift should be installed. II. Pensions and pension certificates should be handled online or through banks so that pensioners need not visit the office often.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Better access (I) and fewer required visits (II) both ease the pensioners' difficulty in practical ways. Both follow.","difficulty":"hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-85","question":"Statement: A survey finds that most two-wheeler riders killed in road accidents in a city were not wearing helmets. Courses of action: I. Every rider caught without a helmet should be jailed for a year. II. Helmet makers should be ordered to cut their prices by half.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Strict enforcement of the helmet rule would be sensible, but a year in jail for a first offence (I) is excessive, and ordering a 50% price cut (II) is arbitrary and unrelated to the cause. Neither follows.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-86","question":"Statement: A bank finds that a large number of its customers' savings accounts have had no transactions for over two years. Courses of action: I. The bank should move the money in these accounts to its own profit account. II. The bank should contact these customers to update their details and reactivate their accounts.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Contacting customers (II) is the proper response. Taking customers' money as profit (I) is illegal and unethical.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-87","question":"Statement: Board results show that students of a district scored far below the state average in English. Courses of action: I. All the English teachers of the district should be dismissed. II. English should be removed from the syllabus of the district's schools.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Dismissing every teacher (I) without any inquiry is extreme, and dropping English (II) would harm students further. Remedial classes or teacher training would follow, but neither of these does.","difficulty":"very-hard","source":"State PSC · SSC CGL"},
  {"id":"reason-critical-reasoning-88","question":"Statement: A portion of the wall of a heritage fort collapsed after heavy rain, though no one was hurt. Courses of action: I. Experts should survey the rest of the fort and repair weak sections at once. II. Visitors should be kept away from the unsafe portions until the survey is complete.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"A survey with repairs (I) prevents further collapse, and keeping visitors away meanwhile (II) prevents injuries. Both are practical and proportionate.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-89","question":"Statement: Several patients have complained that a private hospital overcharged them for routine tests. Courses of action: I. The government should take over the hospital immediately. II. The health department should inquire into the complaints and act against the hospital if they are found true.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"An inquiry followed by action (II) is fair and proper. Taking over the hospital (I) on unverified complaints is drastic.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-90","question":"Statement: Over the past month many first-time online shoppers in a town have lost money after calling fake customer-care numbers found through internet searches. Courses of action: I. People should be advised to use only the contact details given on official websites or apps. II. The police should trace the fake numbers and get them blocked.","options":["Only course of action I follows","Only course of action II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Public awareness (I) prevents new victims, and tracing and blocking the numbers (II) attacks the fraud at its source. Both follow.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-91","question":"Should schools give students some homework during the summer vacation? Arguments: I. Yes, a little homework helps students stay in touch with their studies. II. No, the word 'vacation' does not appear in the school calendar.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":0,"explanation":"I gives a relevant reason linked to learning. II is irrelevant and silly, so it is weak.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-92","question":"Should the retirement age of government employees be raised from 60 to 62? Arguments: I. Yes, people now stay healthy longer, and the government can keep using the skills of experienced staff. II. No, it would delay job openings for young people.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":2,"explanation":"I points to longer working lives and retained experience; II points to fewer vacancies for the young. Both are relevant and significant.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-93","question":"Should the sale of junk food be banned in school canteens? Arguments: I. No, children like junk food. II. Yes, junk food is a major cause of obesity and poor nutrition among children.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":1,"explanation":"II gives a serious health reason. I is weak, because children liking something is no reason to sell it in schools.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-94","question":"Should the use of loudspeakers at night be banned in residential areas? Arguments: I. Yes, noise at night disturbs the sleep of residents, especially the sick, the elderly and students. II. No, loudspeakers are cheap to buy.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":0,"explanation":"I gives a real public-health reason. The price of loudspeakers (II) has nothing to do with whether their use at night should be allowed.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-95","question":"Should all recruitment examinations be conducted only online? Arguments: I. Yes, online examinations are common in developed countries. II. No, many candidates in rural areas do not have reliable access to computers and the internet.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":1,"explanation":"II raises a real issue of fairness and access. I is weak; copying other countries is not a reason by itself.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-96","question":"Should India stop importing crude oil altogether? Arguments: I. Yes, it would save a large amount of foreign exchange. II. No, domestic production is far too small to meet the country's energy needs.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":1,"explanation":"II is strong: stopping imports would cripple transport and industry. I is weak in this context, because the saving in foreign exchange would come at the cost of an energy crisis; the argument ignores feasibility.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-97","question":"Should the minimum age for a car driving licence be lowered from 18 to 16? Arguments: I. Yes, teenagers in some countries are allowed to drive at 16. II. Yes, it will make young people independent sooner.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":3,"explanation":"I merely copies other countries without regard to Indian road conditions, and II offers a vague benefit that ignores road safety. Neither is strong.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-98","question":"Should banks keep their branches open on Sundays too? Arguments: I. Yes, many working people find it hard to visit a bank on weekdays. II. No, bank employees also need a weekly day of rest, and digital banking already covers most needs.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":2,"explanation":"I points to a genuine customer need; II points to staff welfare and existing alternatives. Both are relevant and strong.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-99","question":"Should private cars be banned in the central business districts of large cities during working hours? Arguments: I. Yes, it would reduce congestion and pollution in the busiest parts of the city. II. No, without adequate public transport it would cause great hardship to commuters, the elderly and the disabled.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":2,"explanation":"I names clear benefits; II names a real practical drawback. Both bear directly on the decision, so both are strong.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-100","question":"Should every citizen be required by law to plant a tree each year? Arguments: I. Yes, trees look beautiful. II. No, trees shed leaves that make the roads dirty.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":3,"explanation":"I rests on looks rather than any benefit that justifies a legal duty, and II is a trivial objection. Neither is strong.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-101","question":"Should the government fix the maximum charges for treatment in private hospitals? Arguments: I. Yes, it would protect patients from being overcharged, especially in emergencies. II. No, the government already fixes the fees of private schools.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":0,"explanation":"I gives a relevant reason. II is irrelevant; school fee rules have no bearing on hospital charges, and it does not even argue against the proposal.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-102","question":"Should social-media platforms be required to verify the identity of every user? Arguments: I. Yes, it would curb fake accounts, online harassment and fraud. II. No, collecting identity documents of millions of users would create serious privacy and data-security risks.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":2,"explanation":"I names real harms that verification would reduce; II names real risks it would create. Both are strong.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-103","question":"Should the export of wheat be banned when domestic wheat prices rise sharply? Arguments: I. Yes, keeping food affordable for the country's own citizens must come first. II. No, every ban is always bad.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":0,"explanation":"I gives a relevant reason based on food security. II is a sweeping generalisation ('every', 'always') with no reasoning, so it is weak.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-104","question":"Should all cash transactions above ₹50,000 be banned? Arguments: I. Yes, every developed country has done so. II. Yes, it would help curb black money, and digital payment options are now widely available.","options":["Only argument I is strong","Only argument II is strong","Both I and II are strong","Neither I nor II is strong"],"answer":1,"explanation":"II gives a relevant reason and addresses feasibility. I is weak: it rests on an unverified sweeping claim and on imitation rather than merit.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-105","question":"Statements: I. The state government has announced free bus travel for women on its city buses. II. The number of women travelling on the state's city buses has risen sharply.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":0,"explanation":"Free travel (I) naturally draws more women to the buses (II). I is the cause and II the effect.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-106","question":"Statements: I. The city recorded its highest-ever demand for electricity yesterday. II. Temperatures in the city have stayed above 46°C all this week.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":1,"explanation":"Extreme heat (II) pushes up the use of air-conditioners and coolers, which raises electricity demand (I). II is the cause and I the effect.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-107","question":"Statements: I. Many flights at the city airport were delayed this morning. II. Several vehicles collided on the expressway outside the city this morning.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":3,"explanation":"Neither event causes the other, but both fit a common cause such as dense fog, which reduces visibility for pilots and drivers alike.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-108","question":"Statements: I. The prices of edible oils have risen across the country. II. Sales of two-wheelers have risen in rural areas.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":2,"explanation":"Edible-oil prices depend on crops and imports; rural two-wheeler sales depend on incomes and loans. The two have independent causes.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-109","question":"Statements: I. The government has banned the sale of single cigarettes, allowing only full packets to be sold. II. The number of young smokers in the country has been rising steadily.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":1,"explanation":"Loose cigarettes are cheap and easy for the young to buy. The rise in young smokers (II) prompted the ban (I). II is the cause and I the effect.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-110","question":"Statements: I. Government agencies procured a record quantity of wheat this year. II. Farmers in the wheat-growing states received good winter rainfall this year.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":1,"explanation":"Good winter rain (II) gives a bumper wheat crop, so more wheat is sold to and procured by the agencies (I). II is the cause.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-111","question":"Statements: I. Attendance at the city's cinema halls fell sharply last week. II. Shopkeepers in the city's main markets reported very poor sales last week.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":3,"explanation":"A drop in cinema-going does not cause poor shop sales, nor the other way round. Both, in the same week, point to a common cause such as a curfew, a strike or very heavy rain that kept people at home.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-112","question":"Statements: I. Many large IT companies have frozen fresh hiring this year. II. Engineering colleges report a sharp fall in campus placements this year.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":0,"explanation":"IT companies are the biggest recruiters at engineering campuses, so a hiring freeze (I) leads to fewer placements (II). I is the cause.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-113","question":"Statements: I. All schools in the district have been closed for a week. II. Several bridges in the district have been washed away.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":3,"explanation":"Washed-away bridges point to floods, and floods would also close schools. Bridges being washed away does not by itself close every school; both are effects of a common cause, the floods.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-114","question":"Statements: I. The demand for umbrellas has risen in the city. II. A new metro line has been opened in the city.","options":["Statement I is the cause and statement II is its effect","Statement II is the cause and statement I is its effect","Both statements are effects of independent causes","Both statements are effects of some common cause"],"answer":2,"explanation":"Umbrella demand rises with the rainy season; a metro line opens when construction is complete. The two events have independent causes.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-115","question":"Passage: In 2025 a state's two-wheeler sales grew 18 per cent over the previous year, while its car sales grew only 4 per cent. Dealers said easier loans and a good harvest drove two-wheeler demand, as most of the new buyers came from villages and small towns. Inference: The state's car sales fell in 2025. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Definitely false"],"answer":3,"explanation":"The passage says car sales grew 4 per cent, so a fall contradicts it. Definitely false.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-116","question":"Passage: In 2025 a state's two-wheeler sales grew 18 per cent over the previous year, while its car sales grew only 4 per cent. Dealers said easier loans and a good harvest drove two-wheeler demand, as most of the new buyers came from villages and small towns. Inference: Rural incomes in the state were better in 2025 than in the previous year. How is the inference best described?","options":["Probably true","Data inadequate","Probably false","Definitely false"],"answer":0,"explanation":"A good harvest and more rural buyers suggest rural incomes improved, but the passage gives no income data. Probably true.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-117","question":"Passage: In 2025 a state's two-wheeler sales grew 18 per cent over the previous year, while its car sales grew only 4 per cent. Dealers said easier loans and a good harvest drove two-wheeler demand, as most of the new buyers came from villages and small towns. Inference: Electric models made up more than half of the state's two-wheeler sales in 2025. How is the inference best described?","options":["Definitely true","Data inadequate","Probably false","Definitely false"],"answer":1,"explanation":"The passage does not mention electric vehicles at all, so there is nothing to judge the inference by. Data inadequate.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-118","question":"Passage: The city's air-quality index stayed in the 'severe' category for twelve days in a row in November, the longest such spell in five years. Officials blamed crop-residue burning in neighbouring states and the calm winds of early winter, which trap pollutants near the ground. A ban on construction work brought only a small improvement. Inference: The city has never had a spell of more than twelve 'severe' days in a row. How is the inference best described?","options":["Definitely true","Data inadequate","Probably false","Definitely false"],"answer":1,"explanation":"The passage compares only with the last five years; it says nothing about earlier years. Data inadequate.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-119","question":"Passage: The city's air-quality index stayed in the 'severe' category for twelve days in a row in November, the longest such spell in five years. Officials blamed crop-residue burning in neighbouring states and the calm winds of early winter, which trap pollutants near the ground. A ban on construction work brought only a small improvement. Inference: Stronger winds in November would probably have lowered pollution levels in the city. How is the inference best described?","options":["Probably true","Data inadequate","Probably false","Definitely false"],"answer":0,"explanation":"Calm winds are blamed for trapping pollutants, so stronger winds would likely have dispersed them. This follows from the reasoning given but is not stated. Probably true.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-120","question":"Passage: The city's air-quality index stayed in the 'severe' category for twelve days in a row in November, the longest such spell in five years. Officials blamed crop-residue burning in neighbouring states and the calm winds of early winter, which trap pollutants near the ground. A ban on construction work brought only a small improvement. Inference: The ban on construction work brought air quality in the city back to normal. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Definitely false"],"answer":3,"explanation":"The passage says the ban brought 'only a small improvement' while the index stayed severe. Definitely false.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-121","question":"Passage: A bank's net interest margin narrowed from 3.4 per cent to 3.1 per cent last quarter, even though its total loans grew 15 per cent. The bank said it had cut its lending rates to win market share, while the rates it pays on deposits stayed high because of stiff competition among banks for deposits. Inference: The bank's total loans grew last quarter. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Probably false"],"answer":0,"explanation":"The passage states that total loans grew 15 per cent. Definitely true.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-122","question":"Passage: A bank's net interest margin narrowed from 3.4 per cent to 3.1 per cent last quarter, even though its total loans grew 15 per cent. The bank said it had cut its lending rates to win market share, while the rates it pays on deposits stayed high because of stiff competition among banks for deposits. Inference: The bank raised its lending rates last quarter to protect its margin. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Definitely false"],"answer":3,"explanation":"The passage says the bank cut its lending rates. Definitely false.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-123","question":"Passage: A bank's net interest margin narrowed from 3.4 per cent to 3.1 per cent last quarter, even though its total loans grew 15 per cent. The bank said it had cut its lending rates to win market share, while the rates it pays on deposits stayed high because of stiff competition among banks for deposits. Inference: Deposit rates offered by banks in the market fell sharply last quarter. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Probably false"],"answer":3,"explanation":"Stiff competition for deposits kept the bank's deposit rates high, which suggests rates in the market did not fall sharply. It is not stated outright for all banks, so the inference is probably false.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-124","question":"Passage: Over the last decade, the share of women in a country's manufacturing workforce rose from 18 to 27 per cent. Much of the rise came from electronics-assembly units, which hire women for precision work and have built hostels near their factories. Textile units, which once employed most women factory workers, have seen the share of women in their workforce stay flat. Inference: Electronics-assembly units employ more women today than they did ten years ago. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Probably false"],"answer":0,"explanation":"The passage says much of the rise in women's employment came from these units, which means they took on more women. Definitely true.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-125","question":"Passage: Over the last decade, the share of women in a country's manufacturing workforce rose from 18 to 27 per cent. Much of the rise came from electronics-assembly units, which hire women for precision work and have built hostels near their factories. Textile units, which once employed most women factory workers, have seen the share of women in their workforce stay flat. Inference: The hostels built near factories helped electronics units attract women workers. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Probably false"],"answer":1,"explanation":"The passage links the units' hiring of women with hostels near factories, which suggests the hostels helped, but no causal evidence is given. Probably true.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-126","question":"Passage: Over the last decade, the share of women in a country's manufacturing workforce rose from 18 to 27 per cent. Much of the rise came from electronics-assembly units, which hire women for precision work and have built hostels near their factories. Textile units, which once employed most women factory workers, have seen the share of women in their workforce stay flat. Inference: The share of women in the textile workforce fell sharply over the decade. How is the inference best described?","options":["Definitely true","Probably true","Data inadequate","Definitely false"],"answer":3,"explanation":"The passage says this share 'stayed flat'. Definitely false.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-127","question":"Conclusion: 'Ravi must be unwell, because he has not come to the office today.' Which of the following, if true, most weakens the conclusion?","options":["Ravi seldom misses office","Several employees are down with flu this week","Ravi did not answer his phone this morning","Ravi had applied for leave a week ago to attend his sister's wedding today"],"answer":3,"explanation":"A planned leave for a wedding gives another explanation for his absence, so illness is no longer the likely reason. The flu outbreak and the unanswered phone, if anything, support the conclusion.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-128","question":"Which of the following is a statement of fact rather than an opinion?","options":["Mumbai is the most exciting city in India","Cricket is more enjoyable to watch than football","Summer is the worst season of the year","The Ganga flows through the state of Bihar"],"answer":3,"explanation":"That the Ganga flows through Bihar can be checked against a map. The others express personal judgements ('most exciting', 'more enjoyable', 'worst').","difficulty":"easy","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-129","question":"A shopkeeper says, 'Ever since I put up a big \"Sale\" board, my sales have doubled; the board must be the reason.' The shopkeeper is assuming that:","options":["customers dislike sales","the shop had no customers before the board went up","the board was expensive to make","no other factor, such as the festival season, caused the rise in sales"],"answer":3,"explanation":"To credit the board alone, the shopkeeper must assume nothing else, like a festival rush, drove the rise. The other options are not needed for the argument (and 'no customers' would make 'doubled' meaningless).","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-130","question":"Statement: All the guests at the party were served dinner. Meera was a guest at the party. Which of the following definitely follows?","options":["Meera enjoyed the dinner","Meera hosted the party","Meera was served dinner","Only Meera was served dinner"],"answer":2,"explanation":"Every guest was served dinner and Meera was a guest, so she was served dinner. Nothing is said about whether she enjoyed it or hosted the party, and 'only Meera' contradicts 'all the guests'.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-131","question":"Claim: 'Reading aloud to young children every day improves their vocabulary.' Which of the following, if true, most strengthens the claim?","options":["Many parents enjoy reading to their children","Children's books have become cheaper","Some children prefer cartoons to books","In a study, children randomly assigned to daily reading sessions learned more new words than a similar group without the sessions"],"answer":3,"explanation":"A randomised comparison links daily reading to more words learned while ruling out other differences between the groups. The other options do not touch the effect on vocabulary.","difficulty":"easy","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-132","question":"Statement: The Prime Minister will inaugurate the new airport on Monday, and security in the area has been tightened. Which of the following is the most likely reason for tightening security?","options":["The airport has been closed for good","Monday is a public holiday","To ensure the safety of the Prime Minister and the public during the event","All flights have been cancelled for the year"],"answer":2,"explanation":"A VIP visit and a public event call for extra security. The other reasons are unconnected or contradict the inauguration.","difficulty":"easy","source":"State PSC · SSC CGL"},
  {"id":"reason-critical-reasoning-133","question":"Argument: 'Two of my friends got food poisoning after eating at this restaurant; therefore all the food there is always unsafe.' What is the main flaw in the argument?","options":["It assumes food poisoning is harmless","It ignores the prices charged by the restaurant","It relies on the restaurant's own records","It draws a sweeping conclusion about all the food from just two cases"],"answer":3,"explanation":"Two incidents cannot show that 'all' the food is 'always' unsafe; this is a hasty generalisation. The other options describe things the argument does not do.","difficulty":"easy","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-134","question":"Hospitals in a city treated more cases of heat-stroke this summer than last summer, even though the average summer temperature this year was slightly lower. Which of the following, if true, best explains this?","options":["The city's hospitals have added more beds this year","This summer had more days of extreme heat, even though cooler spells pulled the season's average down","Average temperatures were lower this summer","Heat-stroke is more common in winter than in summer"],"answer":1,"explanation":"Heat-stroke depends on spells of extreme heat, not the seasonal average; more extreme days with a lower average explains the paradox. The second option just restates a fact in the puzzle, and the last is false.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-135","question":"A gym owner claims: 'Members who attend our yoga classes lose more weight than other members, so our yoga classes cause weight loss.' Which of the following, if true, most weakens the claim?","options":["Yoga classes are held early in the morning","The gym charges extra for the yoga classes","Members who join the yoga classes are far more likely than other members to follow a strict diet plan","Some members attend both yoga and weight training"],"answer":2,"explanation":"If yoga members also diet more, the diet rather than yoga may explain their weight loss. The other facts do not affect the cause-and-effect link.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-136","question":"Argument: 'The town should build a second bridge over the river, because the existing bridge is jammed every morning.' The argument assumes that:","options":["the existing bridge is unsafe","bridges are cheap to build","nobody uses the bridge in the evening","a second bridge would reduce the morning jams on the existing bridge"],"answer":3,"explanation":"The remedy (a new bridge) is meant to solve the stated problem (jams), so the argument needs the bridge to relieve the jams. Safety, cost and evening traffic are not part of the reasoning.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-137","question":"A company plans to let its employees work from home two days a week, arguing that this will cut office costs without reducing output. Which of the following, if true, most strengthens the plan?","options":["A six-month trial in one department showed no fall in output while electricity and travel costs dropped","Employees say they like working from home","Rival companies offer free gym membership","The company's office is in the city centre"],"answer":0,"explanation":"The trial supports both parts of the claim: lower costs and unchanged output. Employees liking it does not show output is unaffected.","difficulty":"moderate","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-138","question":"Every member of the debating club is also a member of the quiz club. Some members of the quiz club are in Class XII. Kiran is a member of the debating club. Which of the following must be true?","options":["Kiran is in Class XII","Kiran is a member of the quiz club","Some members of the debating club are in Class XII","Every member of the quiz club is in the debating club"],"answer":1,"explanation":"All debaters are quiz-club members, so Kiran is one. The Class XII quiz members may all be outside the debating club, so the other options need not be true.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-139","question":"A supermarket cut the price of its own-brand biscuits by 20%, yet its total revenue from those biscuits went up. Which of the following, if true, best explains this?","options":["Rival brands also cut their prices","Fewer customers visited the supermarket","The number of packets sold rose by more than a quarter after the price cut","The biscuits were out of stock for a week"],"answer":2,"explanation":"At 80% of the old price, revenue rises only if quantity rises by more than 25% (0.8 × 1.25 = 1). The other options would reduce revenue, not raise it.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-140","question":"Argument: 'Mobile phones damage children's eyesight, since children who own phones are more likely to wear spectacles.' Which of the following, if true, most weakens the argument?","options":["Mobile phones have become cheaper","Spectacles have become fashionable among adults","Many children use phones for online classes","Children who own phones mostly come from families that get their eyes checked regularly, so their eye problems are detected more often"],"answer":3,"explanation":"If phone-owning children simply get tested more, the higher rate of spectacles may reflect detection, not damage. The other options do not touch the causal claim.","difficulty":"moderate","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-141","question":"Statement: A sudden power failure left the city's metro trains stuck between stations for an hour. Courses of action: I. The metro should install backup power to move stranded trains to the nearest station. II. The metro service should be shut down permanently. III. An inquiry should be held into the cause of the power failure.","options":["Only I and III follow","Only II follows","Only I and II follow","All I, II and III follow"],"answer":0,"explanation":"Backup power (I) protects passengers in future and an inquiry (III) finds the cause. Shutting the metro permanently (II) is an absurd overreaction.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-142","question":"A survey of 500 shoppers at a mall found that 60% of them preferred paying by UPI. Which conclusion is best supported by the survey?","options":["60% of all Indians prefer to pay by UPI","A majority of the shoppers surveyed preferred UPI to other modes of payment","Cash payments will soon disappear","Card payments at the mall are falling"],"answer":1,"explanation":"The survey speaks only about the 500 shoppers asked. Extending it to all Indians, or predicting trends in cash and cards, goes beyond the data.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-critical-reasoning-143","question":"Statement: 'The cricket board has decided to hold the final under floodlights in the evening to attract more spectators.' Which of the following is assumed?","options":["Day matches are not allowed","Players prefer night matches","More people are free to attend a match in the evening than during the day","Floodlights cost less than daytime matches"],"answer":2,"explanation":"Moving the match to the evening helps attendance only if more people can come then. The other options are not needed for the decision.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-144","question":"Argument: 'Our new advertisement worked: sales in the month after it ran were 30% higher than in the month before.' Which of the following would be most useful to know in evaluating the argument?","options":["How much the advertisement cost","Which actor appeared in the advertisement","How many colours the advertisement used","Whether sales normally rise in that month every year, even without advertising"],"answer":3,"explanation":"If sales always jump in that month (for example, a festival month), the rise may have nothing to do with the advertisement. The other details do not bear on whether it caused the rise.","difficulty":"moderate","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-145","question":"A city's police claim that their new CCTV network cut street crime by 25% in its first year. Which of the following, if true, most weakens the claim?","options":["Nearby districts with no CCTV network saw a similar fall in street crime that year after night patrols were increased across the region","The CCTV network cost ₹40 crore","Some residents object to the cameras on privacy grounds","Citizens can now report crimes online"],"answer":0,"explanation":"A similar fall where there were no cameras points to another cause, the extra patrols. Online reporting would, if anything, raise recorded crime and strengthen the claim.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-146","question":"Although the number of vehicles using a highway has stayed the same, accidents on it increased after it was widened from four to six lanes. Which of the following, if true, best explains this?","options":["The widening was completed on schedule","The wider road led drivers to drive much faster, and crashes at high speed became more frequent","Better signboards were put up after the widening","Toll charges on the highway were reduced"],"answer":1,"explanation":"Wider lanes raised speeds, and higher speeds mean more crashes even with the same traffic. Better signboards would be expected to reduce accidents, and the other options are irrelevant.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-147","question":"Argument: 'To reduce obesity among teenagers, the government should levy a heavy tax on sugary drinks.' The argument assumes that:","options":["all teenagers are obese","sugary drinks are the only cause of obesity","teenagers will drink fewer sugary drinks if they become costlier","the tax money will be spent on sports facilities"],"answer":2,"explanation":"The tax can reduce obesity only if higher prices cut consumption. Sugary drinks need not be the only cause, and how the money is spent is not part of the argument.","difficulty":"hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-148","question":"Statement: Of the 40 students in a class, 25 like tea, 20 like coffee and 5 like neither. Conclusions: I. Exactly 10 students like both tea and coffee. II. Exactly 15 students like tea but not coffee. III. More students like only coffee than only tea.","options":["Only I follows","Only II and III follow","All I, II and III follow","Only I and II follow"],"answer":3,"explanation":"Students who like at least one = 40 − 5 = 35, so both = 25 + 20 − 35 = 10 (I). Only tea = 25 − 10 = 15 (II). Only coffee = 20 − 10 = 10, fewer than 15, so III is false.","difficulty":"hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-149","question":"Claim: 'Replacing the city's sodium street lamps with LED lamps will reduce the city's lighting bill.' Which of the following, if true, most strengthens the claim?","options":["LED street lamps use about half as much electricity as sodium lamps for the same brightness","LED lamps are available in many colours","Several cities abroad are switching to LED lamps","The electricity tariff may go up next year"],"answer":0,"explanation":"Lower power use for the same light directly supports a smaller bill. Colours and what other cities do are not evidence, and a tariff rise affects any lamp.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-150","question":"Argument: 'Every student who topped the examination last year used Book X. So, if you use Book X, you will top the examination.' Which of the following best describes the flaw in the argument?","options":["It assumes the examination was easy","It treats something the toppers had in common as a guarantee of topping, ignoring users of Book X who did not top","It relies on the opinions of teachers","It ignores the price of Book X"],"answer":1,"explanation":"Using Book X may be common to toppers without being sufficient; many who used it may still have failed to top. That confuses a shared feature with a sure cause.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-151","question":"Argument: 'Since the city's literacy rate rose after it opened 50 public libraries, the libraries must have raised literacy.' Which of the following, if true, most weakens the argument?","options":["The libraries stay open on Sundays","Most library members are school students","The literacy rate had been rising at the same pace for ten years before the libraries opened","Some of the libraries also lend e-books"],"answer":2,"explanation":"If literacy was already rising at the same rate, the libraries made no visible difference, so the rise cannot be credited to them. The other options do not affect the causal link.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-152","question":"A survey found that people who exercise regularly visit doctors more often than people who do not, even though exercise is known to improve health. Which of the following, if true, best explains this?","options":["Exercise improves health","Doctors' fees have gone up","Some people exercise only at weekends","People who exercise regularly tend to be more health-conscious and go for routine check-ups more often"],"answer":3,"explanation":"More visits can reflect routine check-ups by health-conscious people rather than illness. The second option merely restates the puzzle, and the others do not explain the difference.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-153","question":"A bank is offering a lower interest rate on home loans to women borrowers, expecting this to reduce loan defaults. The bank's expectation rests on the assumption that:","options":["loans taken by women borrowers are, on the whole, repaid more reliably than other loans","women do not usually take home loans","the bank's interest income will rise","all borrowers will start borrowing in women's names"],"answer":0,"explanation":"Shifting the loan mix towards women cuts defaults only if women repay more reliably. If women rarely took loans, the offer would barely change defaults.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-154","question":"A study found that districts with more mobile-phone towers have higher recorded cancer rates, and activists concluded that the towers cause cancer. Which of the following, if true, most weakens the conclusion?","options":["Mobile towers emit radio waves","Districts with more towers are the more urbanised ones, where people live longer and cancers are diagnosed more often","Some of the activists live near mobile towers","Mobile companies dispute every such study"],"answer":1,"explanation":"Urbanisation explains both more towers and more recorded cancer (longer lives, better diagnosis), so the link may not be causal. Companies disputing studies is not evidence either way.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-155","question":"A school claims that its new teaching method raised its Class X pass rate from 70% to 85% this year. Which question is most important for evaluating the claim?","options":["How many teachers does the school have?","Were the classrooms repainted this year?","Was this year's examination about as difficult as last year's?","In which year was the school founded?"],"answer":2,"explanation":"If the paper was easier this year, the pass rate would rise without any help from the method. The other questions do not bear on cause and effect.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-156","question":"Statement: 'The state will give free bicycles to all girls who join Class IX in government schools, to reduce school dropouts.' Assumptions: I. The distance to school is one reason girls drop out after Class VIII. II. Girls will use the bicycles to travel to school. III. Boys do not drop out of school.","options":["Only II and III are implicit","Only I and III are implicit","All I, II and III are implicit","Only I and II are implicit"],"answer":3,"explanation":"Bicycles reduce dropouts only if distance is a cause (I) and the girls actually ride them to school (II). Targeting girls does not assume that boys never drop out (III).","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-critical-reasoning-157","question":"Statement: A study shows that over 30% of the fruit and vegetables grown in a state rot before reaching the market because there is not enough cold storage. Courses of action: I. The state should encourage private investment in cold-storage chains. II. Farmers should be asked to grow fewer fruits and vegetables. III. The state should set up food-processing units near the main growing areas.","options":["Only I and III follow","Only II follows","Only I and II follow","All I, II and III follow"],"answer":0,"explanation":"Cold storage (I) and nearby processing (III) both cut wastage. Asking farmers to grow less (II) cuts their income and the food supply instead of fixing the storage gap.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
  {"id":"reason-critical-reasoning-158","question":"Statement: All the doctors at a clinic speak Tamil. Some people who speak Tamil also speak Telugu. Dr. Sen works as a doctor at the clinic and does not speak Telugu. Conclusions: I. Dr. Sen speaks Tamil. II. Some doctors at the clinic do not speak Telugu. III. Every Telugu speaker at the clinic is a doctor.","options":["Only I follows","Only I and II follow","Only II and III follow","All I, II and III follow"],"answer":1,"explanation":"Dr. Sen is a doctor there, so he speaks Tamil (I), and he is a doctor who does not speak Telugu, so II follows. Nothing says who else at the clinic speaks Telugu, so III does not follow.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-critical-reasoning-159","question":"In a town, 60% of households own a two-wheeler and 35% own a car. Every household that owns a car also owns a two-wheeler. Which of the following must be true?","options":["95% of households own at least one vehicle","35% of households own only a car","Exactly 25% of households own a two-wheeler but no car","Exactly 40% of households own only a two-wheeler"],"answer":2,"explanation":"Car owners are a subset of two-wheeler owners, so households with at least one vehicle = 60%, with a two-wheeler but no car = 60 − 35 = 25%, and none own only a car. 40% own neither.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO"},
  {"id":"reason-critical-reasoning-160","question":"Argument: 'Online classes are as effective as classroom teaching, because students in our online course scored the same average marks as students in our classroom course.' Which of the following, if true, most weakens the argument?","options":["The online course cost less","Many online students studied late at night","The same teacher taught both courses","Students in the online course had scored much higher in the entrance test than those in the classroom course"],"answer":3,"explanation":"If the online group started out stronger, equal final marks mean they gained less, so the online course was less effective. The same teacher for both would, if anything, strengthen the comparison.","difficulty":"very-hard","source":"SBI PO · IBPS PO Mains"},
];

export default questions;
